function HL(s, w) { return s.replace(w, '<b class="hl">' + w + '</b>'); }
function P(q, c, w1, w2, i, tr, why) {
  var k = [[0, 1, 2], [1, 0, 2], [2, 0, 1], [1, 2, 0], [0, 2, 1], [2, 1, 0]][i % 6], o = [c, w1, w2];
  return { q: q, o: k.map(function (j) { return o[j]; }), a: k.indexOf(0), tr: tr, why: why };
}
function PL(list) { return list.map(function (x, i) { return P(x[0], x[1], x[2], x[3], i, x[4], x[5]); }); }
function CL(list) { return list.map(function (x) { return { s: x[0], a: x[1], why: x[2] }; }); }

var METIN = "الشَّرْقُ الأَوْسَطُ هِيَ المِنْطَقَةُ الجُغْرَافِيَّةُ الوَاقِعَةُ حَوْلَ البَحْرِ الأَبْيَضِ وَتَمْتَدُّ حَتَّى الخَلِيجِ العَرَبِيِّ. يُسْتَخْدَمُ مُصْطَلَحُ «الشَّرْقِ الأَوْسَطِ» لِلْإِشَارَةِ إِلَى الدُّوَلِ وَالحَضَارَاتِ المَوْجُودَةِ فِي هَذِهِ المِنْطَقَةِ الجُغْرَافِيَّةِ. وَلِلشَّرْقِ الأَوْسَطِ أَهَمِّيَّةٌ دِينِيَّةٌ وَتَارِيخِيَّةٌ وَجُغْرَافِيَّةٌ وَاقْتِصَادِيَّةٌ." +
  "<br>فَمِنَ النَّاحِيَةِ الدِّينِيَّةِ وَالتَّارِيخِيَّةِ، يُعْتَبَرُ الشَّرْقُ الأَوْسَطُ مَهْدَ الدِّيَانَاتِ السَّمَاوِيَّةِ الثَّلَاثَةِ: «الإِسْلَامِ وَاليَهُودِيَّةِ وَالمَسِيحِيَّةِ»، وَيَضُمُّ كَثِيرًا مِنَ الأَمَاكِنِ المُقَدَّسَةِ، فَفِي فِلَسْطِينَ هُنَاكَ المَسْجِدُ الأَقْصَى، وَهُوَ قِبْلَةُ المُسْلِمِينَ الأُولَى، وَفِي مَكَّةَ المُكَرَّمَةِ المَسْجِدُ الحَرَامُ وَالكَعْبَةُ المُشَرَّفَةُ، وَهِيَ قَلْبُ العَالَمِ الإِسْلَامِيِّ وَمَرْكَزُهُ، يَتَوَافَدُ إِلَيْهَا مَلَايِينُ المُسْلِمِينَ كُلَّ عَامٍ لِأَدَاءِ مَنَاسِكِ الحَجِّ وَالعُمْرَةِ، إِضَافَةً إِلَى ذَلِكَ فَهُنَاكَ الكَثِيرُ مِنَ المَعَالِمِ التَّارِيخِيَّةِ مِنَ الحَضَارَاتِ السَّابِقَةِ." +
  "<br>وَمِنَ النَّاحِيَةِ الجُغْرَافِيَّةِ يَقَعُ الشَّرْقُ الأَوْسَطُ وَسَطَ العَالَمِ، وَيُشْرِفُ عَلَى كَثِيرٍ مِنَ البِحَارِ وَالمُحِيطَاتِ المُهِمَّةِ، وَلَهُ كَثِيرٌ مِنَ المَنَافِذِ وَالمَضِيقَاتِ الحَيَوِيَّةِ، مِنْهَا مَضِيقُ «هُرْمُزَ» عَلَى الخَلِيجِ العَرَبِيِّ، وَمَضِيقُ «بَابِ المَنْدَبِ» عَلَى المُحِيطِ الهِنْدِيِّ، وَمَضِيقُ «جَبَلِ طَارِقٍ» عَلَى المُحِيطِ الأَطْلَسِيِّ، وَمَضِيقُ البُوسْفُورِ بَيْنَ قَارَّتَيْ آسِيَا وَأُورُوبَّا، وَ«قَنَاةُ السُّوَيْسِ» الَّتِي تَرْبِطُ البَحْرَ الأَبْيَضَ بِالبَحْرِ الأَحْمَرِ." +
  "<br>أَمَّا مِنَ النَّاحِيَةِ الاقْتِصَادِيَّةِ فَإِنَّ الشَّرْقَ الأَوْسَطَ يَحْتَوِي عَلَى كَثِيرٍ مِنَ الثَّرَوَاتِ الطَّبِيعِيَّةِ وَالمَعْدِنِيَّةِ، وَعَلَى رَأْسِهَا الثَّرْوَةُ النِّفْطِيَّةُ المُهِمَّةُ فِي حَيَاتِنَا اليَوْمَ، كَمَا تُوجَدُ كَثِيرٌ مِنَ المَعَادِنِ فِي الشَّرْقِ الأَوْسَطِ مِثْلُ الحَدِيدِ، وَالنُّحَاسِ، وَالبُوتَاسِ، وَالأَلُمِنْيُومِ. وَالثَّرْوَةُ السَّمَكِيَّةُ تُشَكِّلُ جُزْءًا مُهِمًّا مِنْ ثَرَوَاتِ الشَّرْقِ الأَوْسَطِ، وَكَذَلِكَ تَمْتَلِكُ مَنَاطِقُ الشَّرْقِ الأَوْسَطِ أَرَاضِيَ خِصْبَةً لِلزِّرَاعَةِ." +
  "<br>وَإِضَافَةً إِلَى مَا سَبَقَ تَتَمَيَّزُ دُوَلُ الشَّرْقِ الأَوْسَطِ بِجَمَالِ مُنَاخِهَا، لِذَلِكَ يَقْصِدُهَا السُّيَّاحُ مِنْ كُلِّ أَنْحَاءِ العَالَمِ.";
var METIN_TR = "Orta Doğu, Akdeniz’in (Ak Deniz) çevresinde yer alan ve Basra (Arap) Körfezi’ne kadar uzanan coğrafî bölgedir. “Orta Doğu” terimi bu coğrafî bölgedeki devletleri ve medeniyetleri belirtmek için kullanılır. Orta Doğu’nun dinî, tarihî, coğrafî ve iktisadî önemi vardır." +
  "<br>Dinî ve tarihî açıdan Orta Doğu üç semavî dinin (İslam, Yahudilik ve Hristiyanlık) beşiği kabul edilir ve birçok kutsal mekânı içine alır: Filistin’de Müslümanların ilk kıblesi Mescid-i Aksâ vardır; Mekke-i Mükerreme’de Mescid-i Haram ve Kâbe-i Müşerrefe vardır; Mekke İslam dünyasının kalbi ve merkezidir, her yıl milyonlarca Müslüman hac ve umre ibadetlerini yapmak için oraya akın eder. Bunun yanında önceki medeniyetlerden kalma birçok tarihî eser de vardır." +
  "<br>Coğrafî açıdan Orta Doğu dünyanın ortasında yer alır; birçok önemli denize ve okyanusa bakar. Birçok hayatî çıkışı ve boğazı vardır: Basra Körfezi’ndeki Hürmüz Boğazı, Hint Okyanusu’ndaki Bâbülmendeb Boğazı, Atlas Okyanusu’ndaki Cebelitarık Boğazı, Asya ile Avrupa kıtaları arasındaki İstanbul Boğazı ve Akdeniz’i Kızıldeniz’e bağlayan Süveyş Kanalı." +
  "<br>İktisadî açıdan ise Orta Doğu birçok tabiî ve madenî zenginlik içerir; bunların başında bugün hayatımızda çok önemli olan petrol zenginliği gelir. Ayrıca Orta Doğu’da demir, bakır, potas ve alüminyum gibi birçok maden bulunur. Balık zenginliği de Orta Doğu’nun zenginliklerinin önemli bir parçasını oluşturur; Orta Doğu bölgeleri tarıma elverişli verimli topraklara da sahiptir." +
  "<br>Bütün bunlara ek olarak Orta Doğu ülkeleri ikliminin güzelliğiyle öne çıkar; bu yüzden dünyanın her yerinden turistler oraya gider.";
